WITH unpacked AS (SELECT id, plan, effective_from, currency, tier_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE YEAR(effective_from) >= 2024) SELECT *, AVG(avg_tier_price) OVER (ORDER BY avg_tier_price, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS avg_tier_price_avg_5, AVG(lowest_price) OVER w_hist AS lowest_price_avg_2, NTILE(5) OVER (PARTITION BY plan, currency ORDER BY entry_price DESC, id) AS entry_price_bucket FROM unpacked WINDOW w_hist AS (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)
